# coding: utf-8
from lesson_authoring import entry as E
M=[['日耳曼语系的 mis-，古英语已有','方向或结果不对；不是希腊“厌恶”']]
T=M+[['英语 mis- + take，或相关古诺尔斯 mistaka；两条路线可能相互影响','拿错、理解错'],['中古英语 mistaken → 英语 mistake','误认、弄错；后来也作名词“错误”']]
LE=M+[['古英语 mislǣdan → 中古英语 misleden','把人带错方向'],['英语 mislead','使人得出错误印象或判断']]
U=M+[['中古英语 mis- + understand','理解错'],['英语 misunderstand','误解某人的话、意思或意图']]
WB=[
E('mistake','/mɪˈsteɪk/','错误；弄错、误认','本来该认作甲，却拿成或当成了乙。','现代可拆 mis- + take；历史还涉及古诺尔斯 mistaka，不能简单认定它完全是在现代英语里拼出来的。',T,'动词 mistake 常用 mistake A for B：把 A 误认成 B。名词 a mistake 是一次错误，make a mistake 是犯错，by mistake 是误做了某事。它通常不自动说明你故意做坏事。','make a mistake；by mistake；mistake A for B。','mistake 的过去式 mistook，过去分词 mistaken。不要把 make a mistake 写成 do a mistake。',('I sent the file to the wrong person by mistake.','我误把文件发给了不该收的人。'),('In the dark, I mistook the coat for a person.','黑暗中，我把那件外套误看成了一个人。'),sources=['https://www.etymonline.com/word/mistake','https://en.wiktionary.org/wiki/mistake']),
E('mistaken','/mɪˈsteɪkən/','弄错的；错误的；mistake 的过去分词','你心里的判断很确定，但它与实际情况对不上。','mistake 的过去分词；作形容词时表示判断或认识有误。',T+[['过去分词 mistaken → 形容词用法','处在误认或判断错误的状态']],'You are mistaken 是“你弄错了”，不是“你是一个错误”。a mistaken belief 是错误认识，mistaken identity 是认错人。这里的 -en 是不规则动词变化的一部分，不要当成表示“使变成”的派生后缀。','be mistaken about something；a mistaken belief；a case of mistaken identity。','mistaken 描述判断错了的人或认识；misleading 描述容易把别人带向错误判断的信息。',('If I’m not mistaken, the meeting starts at ten.','如果我没记错，会议十点开始。'),('She was mistaken about the delivery date.','她把送货日期弄错了。'),sources=['https://en.wiktionary.org/wiki/mistaken','https://www.etymonline.com/word/mistake']),
E('mistakenly','/mɪˈsteɪkənli/','错误地；误以为；误做了','某个动作或判断发生了，但它建立在一个错误认识上。','mistaken + -ly，把“弄错的”变成描述动作方式的副词。',T+[['mistaken + -ly → mistakenly','由于弄错而作出某个判断或动作']],'mistakenly believe 强调相信的内容不对；mistakenly delete 强调本不想删这项，却删了。这个词让读者看到错误发生在哪里，比笼统地说 badly 更清楚。','mistakenly believe；mistakenly assume；mistakenly identify。','mistakenly 常突出弄错；accidentally 更广泛地表示意外，并不总涉及认错对象或错误判断。',('I mistakenly assumed that the shop was open on Sundays.','我误以为这家店星期天也开门。'),('The system mistakenly identified the message as spam.','系统误把这条消息识别成了垃圾信息。'),sources=['https://en.wiktionary.org/wiki/mistakenly','https://en.wiktionary.org/wiki/mistaken']),
E('mislead','/ˌmɪsˈliːd/','误导；使产生错误印象','像把人带上岔路，只不过被带偏的是理解和判断。','mis- “错误地” + lead“带领”；这类形式在古英语就已存在。',LE,'mislead 可以说人故意误导，也可以说一个不清楚的图表无意中让人理解错。重点在信息把读者带偏了，不是一定有人撒了一个明确的谎。过去式和过去分词都是 misled /ˌmɪsˈled/。','mislead someone about something；mislead someone into believing something。','mislead 是造成错误认识；lie 是说谎。省掉关键信息也可能 mislead，即使单独每句话都是真的。',('The title could mislead readers about the article’s main point.','这个标题可能让读者误解文章的重点。'),('The advertisement misled me into thinking that delivery was free.','那则广告误导了我，让我以为送货免费。'),sources=['https://en.wiktionary.org/wiki/mislead','https://www.etymonline.com/word/mislead']),
E('misleading','/ˌmɪsˈliːdɪŋ/','误导性的；容易造成错误印象的','表面看起来像在说明事实，实际却把人引向不准确的结论。','mislead + -ing，分词作形容词描述信息的效果。',LE+[['mislead + -ing → misleading','容易把理解带偏的']],'a misleading average 可能数字算得没错，却掩盖了不同群体的差异；a misleading headline 可能夸大正文内容。所以 misleading 不只等于“数字全是假的”，也包括呈现方式造成的错觉。','a misleading impression；misleading information；a misleading comparison。','misleading 是使人误解的；misunderstood 是已经被人误解的。一个标题可能 misleading，一位讲话者可能 misunderstood。',('The graph is misleading because the vertical axis starts at ninety.','这张图容易误导，因为纵轴从九十开始。'),('The phrase gives a misleading impression of how easy the task is.','这个说法让人误以为任务很容易。'),sources=['https://en.wiktionary.org/wiki/misleading','https://www.etymonline.com/word/mislead']),
E('misunderstand','英 /ˌmɪsʌndəˈstænd/；美 /ˌmɪsʌndərˈstænd/','误解；理解错','话听到了，也给它安上了意思，只是安错了。','mis- “错误地” + understand“理解”；不要把整词硬拆成“站错在下面”。',U,'misunderstand 不一定是完全没听懂，而是自以为明白，却抓错了意思。You misunderstood me 常是在纠正对方对自己意图的理解。过去式和过去分词是 misunderstood。','misunderstand a question；misunderstand someone’s intentions；Don’t misunderstand me.','not understand 是不理解，misunderstand 是理解成了错误的意思。两者造成的问题不一样。',('I misunderstood the instructions and filled in the wrong section.','我误解了说明，填错了栏目。'),('Don’t misunderstand me—I like the idea, but we need more time.','别误会我的意思，我喜欢这个想法，只是我们需要更多时间。'),sources=['https://en.wiktionary.org/wiki/misunderstand','https://www.etymonline.com/word/misunderstand']),
E('misunderstanding','英 /ˌmɪsʌndəˈstændɪŋ/；美 /ˌmɪsʌndərˈstændɪŋ/','误解；误会；由误会造成的分歧','双方拿着不同版本的意思继续交流，于是越说越不在一条线上。','misunderstand + -ing，表示误解这件事或其结果。',U+[['misunderstand + -ing → misunderstanding','理解错误；由此产生的误会或分歧']],'a misunderstanding 可以是对安排、词义或意图的误会；clear up a misunderstanding 就是把误会说明白。有时它也委婉指双方闹了别扭，但不能据此把每次严重冲突都轻描淡写地叫误会。','a misunderstanding about something；clear up a misunderstanding；avoid misunderstandings。','miscommunication 强调沟通出了问题；misunderstanding 强调有人理解错了。前者可能造成后者。',('There was a misunderstanding about who would book the room.','大家对谁来订房间有了误会。'),('A short phone call cleared up the misunderstanding.','一个简短的电话就澄清了误会。'),sources=['https://en.wiktionary.org/wiki/misunderstanding','https://www.etymonline.com/word/misunderstanding']),
E('mismatch','名词常 /ˈmɪsmætʃ/；动词 /ˌmɪsˈmætʃ/','不匹配；错配；把不相配的东西配在一起','两个东西被放到一起，但大小、能力、需求或条件对不上。','mis- “不对” + match“配合、匹配”。',M+[['英语 mis- + match','配错、配不上'],['mismatch 作动词或名词','错误配对；两者之间的不协调']],'a mismatch between skills and jobs 不是说技能一无是处，而是岗位需要的和现有的对不上。比赛中的 a mismatch 则常指双方实力悬殊。核心是关系不合适，不是某一方单独不好。','a mismatch between A and B；a skills mismatch；a complete mismatch。','difference 只是有差别；mismatch 表示差别造成不适合或不协调。不同也可能互补，未必 mismatch。',('There is a mismatch between the training and the work employees actually do.','培训内容与员工实际从事的工作不匹配。'),('The match was a complete mismatch between an expert and a beginner.','这场比赛是一位高手和一名新手之间实力悬殊的对决。'),sources=['https://en.wiktionary.org/wiki/mismatch','https://www.merriam-webster.com/dictionary/mismatch']),
E('mismatched','/ˌmɪsˈmætʃt/','不相配的；错配的','已经配成一组，但一眼看去或实际使用起来不协调。','mismatch + -ed；结尾 -ed 在 /tʃ/ 后读 /t/。',M+[['英语 mismatch','把东西配得不合适'],['mismatch + -ed → mismatched','配在一起却不协调的']],'mismatched socks 是两只不配套的袜子；mismatched expectations 是双方预期对不上。有时 mismatched 的物件是故意搭出来的风格，不一定是失误，要看上下文。','mismatched socks；mismatched furniture；mismatched expectations。','mismatch 常是名词，mismatched 是形容词。mixed 只是混合了，未必不协调。',('He arrived wearing mismatched socks.','他穿着两只不配套的袜子来了。'),('The café’s mismatched chairs give it a relaxed feel.','咖啡馆里各不相配的椅子让它显得很随意自在。'),sources=['https://en.wiktionary.org/wiki/mismatched','https://www.merriam-webster.com/dictionary/mismatched']),
E('mistrust','/ˌmɪsˈtrʌst/','不信任；怀疑','心里不肯把可靠性这一票投给对方，总觉得哪里靠不住。','mis- + trust；这里已经形成“不信任”的意思，不应按字面译成“信任错了人”。',M+[['中古英语 mistrust／mistrusten','怀疑、不信任'],['英语 mistrust','名词或动词：不信任']],'mistrust 可指对人的怀疑，也可指对某种制度、数字或技术的不信任。a climate of mistrust 是大家互相疑虑的气氛。它不必达到 hatred“憎恨”的程度。','mistrust someone；mistrust of institutions；mutual mistrust。','mistrust 与 distrust 大量重叠，不必硬分成一个一定“怀疑”、另一个一定“确认不可信”。语境和搭配更有用。',('Years of secrecy created deep mistrust between the two teams.','多年的信息不透明让两个团队之间产生了深深的不信任。'),('I mistrust figures that come without any explanation of how they were collected.','对于那些不说明收集方法的数字，我抱有怀疑。'),sources=['https://www.etymonline.com/word/mistrust','https://en.wiktionary.org/wiki/mistrust']),
]
